// --- inputs -----------------------------------------------------------------
// The agent's pick from the lead grid on the previous screen.
let selected_lead = views.raintree__find_leads;
let lead_pn = selected_lead.pn;

// --- outputs ----------------------------------------------------------------
// Same two writes node 131 makes for the hand-typed path, so everything downstream
// of Get Patient Details behaves identically however the patient number arrived.
// The transform is the dot-path merge field in the Get Patient Details endpoint URL.
ZT.setFormData("patient_number", lead_pn);

// A lead that has not been converted has no chart yet, so pn is blank. Node 161 sends
// those to Lead Already Exists (129), where the agent converts it and enters the number.
ZT.setFormData("has_lead_patient_number", String(lead_pn || "").trim() !== "" ? "true" : "false");
ZT.setTransformData("patient", { pn: lead_pn });

