// Constants
const PEC_TYPE = "PHONE: Phone Referral";
const MARKETING_REFERRAL = "00000";
const TESTING_COST_CODE = "ZZZ";
const SPECIALTY_PRIMARY_REASON = "Episode of care";
const DEFAULT_REQ_VALUE = "Did not have";
const DEFAULT_NO_EMAIL = "Pending email";
const PEC_RESOURCE_CODE = "123";
const PCP = "Primary Care Physician";
const NONE_SPECIALTY = "PT";
const TASKS = {
  noReferral: {
    type: "Patient Engagement Center",
    subType: "PEC - No Referral",
  },
};

// Utils Functions
const formatDOB = () => {
  const [month, day, year] = patient_dob.trim().split("/");
  return `${year}-${month.padStart(2, "0")}-${day.padStart(2, "0")}`;
};

const formatMailingAddress = () => {
  const address_line_2 =
    typeof patient_address_line_2 !== "undefined"
      ? patient_address_line_2.trim()
      : "";
  return `${patient_address_line_1} ${address_line_2}`.trim();
};

const formatApptDate = () => {
  const [month, day, year] = appt_date.trim().split("/");
  return `${year}-${month.padStart(2, "0")}-${day.padStart(2, "0")}T00:00:00Z`;
};

const formatApptTimeStart = () => {
  const time = appt_time.trim().toLowerCase();
  const isMorning = time.indexOf("a") !== -1;
  const [hour, minutes] = time
    .split(":")
    .map((x) => parseInt(x.replaceAll(/[a-z]/g, "")));
  const offset = hour === 12 || isMorning ? 0 : 12;
  const hourStr = (hour + offset).toString().padStart(2, "0");
  const minutesStr = minutes.toString().padStart(2, "0");
  return `${hourStr}:${minutesStr}:00`;
};

const formatApptTimeEnd = (startDate, offset) => {
  const [hour, minutes, seconds] = startDate.split(":").map((x) => parseInt(x));
  const hourStr =
    hour + offset === 24 ? "00" : (hour + offset).toString().padStart(2, "0");
  const minutesStr = minutes.toString().padStart(2, "0");
  const secondsStr = seconds.toString().padStart(2, "0");
  return `${hourStr}:${minutesStr}:${secondsStr}`;
};

// const validateEmail = () => {
//   const emailRegex = /^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$/;
//   return emailRegex.test(patient_email_address.trim());
// };

const getCaseName = () => {
  const specialty = specialty_needed_name.trim();
  const otherSpecialty =
    specialty.toLowerCase() !== "ot" && specialty.toLowerCase() !== "none";
  let caseName = "";
  if (otherSpecialty) {
    caseName +=
      body_part === ""
        ? specialty_needed_name
        : `${body_part}, ${specialty_needed_name}`;
  } else {
    caseName += body_part === "" ? therapy_type : body_part;
  }
  return caseName;
};

const createZingtreeURL = (sessionId, agentEmail) => {
  let source = "";
  let contactId = "";
  let agentFirstName = "";

  if (agentEmail !== "System") source = `&source=${agentEmail}`;
  if (typeof contact_id !== "undefined" && contact_id.trim() !== "")
    contactId = `&zv_contact_id=${contact_id}`;
  if (
    typeof agent_first_name !== "undefined" &&
    agent_first_name.firstName !== ""
  )
    agentFirstName = `&zv_agent_first_name=${agent_first_name}`;

  // TODO: Uncomment the return - LIVE VERSION
  return `https://zingtree.com/live/632727963?agent_mode=1${source}${contactId}&zv_clinic_phone=${clinic_phone}${agentFirstName}&session_id=${sessionId}&apikey=REDACTED_ZINGTREE_APIKEY#93`;
  // TODO: Comment the return - PREVIEW VERSION
  // return `https://zingtree.com/preview/632727963?tree_id=632727963&agent_mode=1${source}${contactId}&zv_clinic_phone=${clinic_phone}${agentFirstName}&session_id=${sessionId}&is_preview=1#93`;
};

// Main Functions
// Clinic information
const getClinicInfo = () => {
  return {
    costCode: appt_clinic_cost_code.trim().startsWith("UT")
      ? TESTING_COST_CODE
      : appt_clinic_raintree_code.trim(),
    name: appt_clinic.trim(),
  };
};

// Patietn Information
const getPatientInfo = (sessionId, summaryInfo) => {
  // Patient Metadata
  const isMinor = typeof parent_guardian_first_name !== "undefined";
  const patient = {
    id: `P-${sessionId}`,
    dataType: PEC_TYPE,
    haveYouBeenBefore: false,
    isMinor: isMinor,
    zingtreeSummaryInformation: summaryInfo,
  };

  // Personal Information
  const haveEmail = !isMinor ? patient_has_email === 'Yes' : false;
  const personalInformation = {
    firstName: patient_first_name.trim(),
    lastName: patient_last_name.trim(),
    marketingReferral: MARKETING_REFERRAL,
    dbo: formatDOB(),
    birthSex: patient_birth_sex.trim().slice(0, 1).toUpperCase(),
    mailingAddress: formatMailingAddress(),
    phoneNumber: patient_phone_number.trim(),
    haveEmail: haveEmail,
    email: haveEmail ? patient_email_address.trim() : DEFAULT_NO_EMAIL,
    zipCode: patient_zipcode.trim(),
  };
  patient["personalInformation"] = personalInformation;

  // Visit Reason Assignment
  const visitReasonAssignment = {
    whatHereFor: therapy_type.trim(),
    primaryReason:
      specialty_needed_name.trim().toLowerCase() !== "ot" &&
      specialty_needed_name.trim().toLowerCase() !== "none"
        ? SPECIALTY_PRIMARY_REASON
        : body_part,
    howHearAboutUs: how_did_you_hear_about_us.trim(),
    bodyPart: body_part.trim(),
  };
  patient["visitReasonAssignments"] = visitReasonAssignment;

  return patient;
};

// Appointment Information
const getApptInfo = (sessionId, summaryInfo) => {
  // Set Initial Time for Appointment
  const timeFrom = formatApptTimeStart();
  const specialty = specialty_needed_name.trim();
  // Appt Info
  return {
    id: `APT-${sessionId}`,
    name: `${therapy_type}IE - ${sessionId}`,
    type: `${therapy_type}IE`,
    therapyType: therapy_type.trim(),
    specialty: specialty.toLowerCase() !== "none" ? specialty : NONE_SPECIALTY,
    preferredLocation: appt_clinic_cost_code.trim().startsWith("UT")
      ? TESTING_COST_CODE
      : appt_clinic_raintree_code.trim(),
    appointmentDate: formatApptDate(),
    timeFrom: timeFrom,
    timeTo: formatApptTimeEnd(timeFrom, 1),
    resourceCode: PEC_RESOURCE_CODE,
    agentNotes: summaryInfo,
    caseName: getCaseName(),
    tasks: getTasks(), // Tasks
    contacts: getContacts(), // Contacts
  };
};

// Tasks
const getTasks = () => {
  const noPrescriptionFound = typeof is_prescription_found !== "undefined" && is_prescription_found === "no";
  const noTreatmentReferral = typeof treatment_referral !== "undefined" && treatment_referral !== "Yes";
  const noReferralTask = noPrescriptionFound || noTreatmentReferral;
  const tasks = [];

  // No Referral
  if (noReferralTask) tasks.push(TASKS.noReferral);

  return tasks;
};

// Contacts
const getContacts = () => {
  const contacts = [];
  const noPrescriptionFound = typeof is_prescription_found !== "undefined" && is_prescription_found === "no";
  const noTreatmentReferral = typeof treatment_referral !== "undefined" && treatment_referral === "No";
  const hasNoReferral = noPrescriptionFound || noTreatmentReferral;
  const isMinor = typeof parent_guardian_first_name !== "undefined";
  const hasEmergencyContact =
    typeof emergency_contact_first_name !== "undefined";
  const guardianIsEmergencyContact =
    hasEmergencyContact &&
    isMinor &&
    parent_guardian_first_name.trim().toLowerCase() ===
      emergency_contact_first_name.trim().toLowerCase() &&
    parent_guardian_last_name.trim().toLowerCase() ===
      emergency_contact_last_name.trim().toLowerCase() &&
    parent_guardian_phone_number.trim() ===
      emergency_contact_phone_number.trim();

  // PCP
  if (hasNoReferral) contacts.push(getPCPInforamtion());
  // Guardian
  if (isMinor)
    contacts.push(getGuardianInformation(guardianIsEmergencyContact));
  // Emergency Contact
  if (!guardianIsEmergencyContact && hasEmergencyContact)
    contacts.push(getEmergencyContactInfo());

  return contacts;
};

// PCP
const getPCPInforamtion = () => {
  return {
    type: PCP,
    firstName:
      typeof primary_care_physician_first_name !== "undefined" &&
      primary_care_physician_first_name.trim() !== ""
        ? primary_care_physician_first_name.trim()
        : DEFAULT_REQ_VALUE,
    lastName: primary_care_physician_last_name,
    phoneNumber:
      typeof primary_care_physician_phone_number !== "undefined"
        ? primary_care_physician_phone_number.trim()
        : "",
    isEmergencyContact: false,
    isAuthorizeRepresentative: false,
    isGuardian: false,
  };
};

// Guardian Information
const getGuardianInformation = (isEmergencyContact) => {
  const haveEmail = patient_has_email === 'Yes';
  return {
    type: patient_relationship_to_caller.trim(),
    firstName: parent_guardian_first_name.trim(),
    lastName: parent_guardian_last_name.trim(),
    phoneNumber: parent_guardian_phone_number.trim(),
    email: haveEmail ? patient_email_address.trim() : "",
    isEmergencyContact: isEmergencyContact,
    isAuthorizeRepresentative: true,
    isGuardian: true,
  };
};

// Emergency Contact Information
const getEmergencyContactInfo = () => {
  return {
    type: emergency_contact_relationship.trim(),
    firstName: emergency_contact_first_name.trim(),
    lastName: emergency_contact_last_name.trim(),
    phoneNumber: emergency_contact_phone_number.trim(),
    isEmergencyContact: true,
    isAuthorizeRepresentative:
      is_emergency_contact_authorized_representative === "Yes",
    isGuardian: false,
  };
};

// Zingtree Summary
const getSummary = () => {
  let agentInfo = "";
  if (typeof agent_email !== "undefined" && agent_email !== "") {
    agentInfo = `Agent: ${agent_email}\n\n`;
  }
  // Reason to Schedule and Post Op
  const reasonToSchedule = `Reason for Schedule on Date: ${scheduled_out_reason}\n`;

  let postOp = "";
  if (
    typeof post_op_expected_date !== "undefined" &&
    post_op_expected_date !== ""
  ) {
    postOp += `\nPost Op Date: ${post_op_expected_date}\n`;
  }

  // Caller Information for Summary
  const callerInfo = `\nCaller Info\nFirst Name: ${caller_first_name}\nLast Name: ${caller_last_name}\nPhone Number: ${caller_phone_number}\n`;

  // Patient Information for Summary
  const mailingAddress = formatMailingAddress();
  const birthSex =
    typeof patient_pronouns !== "undefined" &&
    patient_pronouns !== "" &&
    patient_pronouns !== "[not offered]"
      ? `${patient_birth_sex} (${patient_pronouns})`
      : patient_birth_sex;
  const patientInfo = `\nPatient Info\nFirst Name: ${patient_first_name}\nLast Name: ${patient_last_name}\nRelationship to Patient: ${patient_relationship_to_caller}\nDOB: ${patient_dob}\nBirth Sex: ${birthSex}\nPhone Number: ${patient_phone_number}\nEmail: ${patient_email_address}\nMailing Address: ${mailingAddress}\n${patient_city}, ${patient_state} ${patient_zipcode}\n`;

  // Medical Information for Summary
  const preferredLocation =
    typeof new_appointment_clinic !== "undefined"
      ? `Preferred Location: ${new_appointment_clinic} (${new_appointment_clinic_raintree_code})\n`
      : "";
  const bodyPart =
    typeof body_part !== "undefined" && body_part !== ""
      ? `Body Part: ${body_part}\n`
      : "";
  const additionalTreatment =
    typeof additional_treatment_notes !== "undefined" &&
    additional_treatment_notes !== ""
      ? `Additional Treatment Notes: ${additional_treatment_notes}\n`
      : "";
  const medicalInformation = `\nMedical Information\nWhat are you here for? ${therapy_type}\n${preferredLocation}How did you hear about us? ${how_did_you_hear_about_us}\n${bodyPart}${additionalTreatment}Specialty Needed: ${specialty_needed_name}\n`;

  // Referral
  let pcp = "";
  let referringPhysician = "";
  let referringProviderNote = "";
  let referredToIvy = "";
  if (typeof referring_physician_last_name !== "undefined") {
    const referringPhysicianInfo =
      `${referring_physician_first_name} ${referring_physician_last_name}   ${referring_physician_phone_number}`.trim();
    referringPhysician += `\nReferring Physician: ${referringPhysicianInfo}\n`;
  }
  if (typeof primary_care_physician_last_name !== "undefined") {
    const pcpInfo =
      `${primary_care_physician_first_name} ${primary_care_physician_last_name}   ${primary_care_physician_phone_number}`.trim();
    pcp += `\nPCP: ${pcpInfo}\n`;
  }
  if (typeof no_referral_note !== "undefined") {
    referringProviderNote += `\nReferring Provider Note: ${no_referral_note}\n`;
  }
  if (typeof treatment_referral !== "undefined" && treatment_referral === "Yes") {
    referredToIvy += `\nReferred to Ivy: ${referred_to_ivy}\n`;
  }

  // Self Pay & Insurance
  let selfPay = "";
  let insurance = "";
  let secondInsurance = "";
  if (typeof is_private_pay_patient !== "undefined" && is_private_pay_patient) {
    selfPay += `\nPrivate Pay Patient (Quoted \$${appt_ie_pricing} for IE and \$${appt_dv_pricing} for follow-ups)`;
  }
  if (
    typeof patient_insurance_other !== "undefined" &&
    patient_insurance_other !== ""
  ) {
    const missingInsurance =
      typeof missing_insurance_details !== "undefined" &&
      missing_insurance_details !== ""
        ? `Reason for no insurance details: ${missing_insurance_details}\n`
        : "";
    const middleInitial =
      typeof subscriber_middle_initial !== "undefined" &&
      subscriber_middle_initial !== ""
        ? `Subscriber Middle Initial: ${subscriber_middle_initial}\n`
        : "";
    const groupNumber =
      typeof group_number !== "undefined" && group_number !== ""
        ? `Group Number: ${group_number}\n`
        : "";
    const insuranceInfo =
      typeof subscriber_first_name !== "undefined" &&
      subscriber_first_name !== ""
        ? `\nSubscriber First Name: ${subscriber_first_name}\n${middleInitial}Subscriber Last Name: ${subscriber_last_name}\nRelationship to Insured: ${subscriber_relationship_to_patient}\nSubscriber DOB: ${subscriber_dob}\n${groupNumber}Subscriber/Member ID: ${subscriber_id}`
        : "";

    insurance += `\nInsurance Info\n${missingInsurance}Name of Insurance: ${patient_insurance_other}\nEffective Date: 01/01/${effective_year}${insuranceInfo}\n`;
  }
  if (
    typeof patient_secondary_insurance_other !== "undefined" &&
    patient_secondary_insurance_other !== ""
  ) {
    const middleInitial =
      typeof secondary_subscriber_middle_initial !== "undefined" &&
      secondary_subscriber_middle_initial !== ""
        ? `Subscriber Middle Initial: ${secondary_subscriber_middle_initial}\n`
        : "";
    const groupNumber =
      typeof secondary_group_number !== "undefined" &&
      secondary_group_number !== ""
        ? `Group Number: ${secondary_group_number}\n`
        : "";
    const insuranceInfo =
      typeof secondary_subscriber_first_name !== "undefined" &&
      secondary_subscriber_first_name !== ""
        ? `\nSubscriber First Name: ${secondary_subscriber_first_name}\n${middleInitial}Subscriber Last Name: ${secondary_subscriber_last_name}\nRelationship to Insured: ${secondary_subscriber_relationship_to_patient}\nSubscriber DOB: ${secondary_subscriber_dob}\n${groupNumber}Subscriber/Member ID: ${secondary_subscriber_id}`
        : "";

    secondInsurance += `Secondary Insurance Info\nName of Insurance:${patient_secondary_insurance_other}\n$Effective Date: 01/01/${effective_year}${insuranceInfo}\n`;
  }

  // Parent or Guardian
  let parentGuardian = "";
  if (
    typeof parent_guardian_first_name !== "undefined" &&
    parent_guardian_first_name !== ""
  ) {
    parentGuardian += `\nParent/Guardian\nFirst Name: ${parent_guardian_first_name}\nLast Name: ${parent_guardian_last_name}\nPhone Number: ${parent_guardian_phone_number}\n`;
  }

  // Emergency Contact
  let emergencyContact = "";
  if (
    typeof emergency_contact_first_name !== "undefined" &&
    emergency_contact_first_name !== ""
  ) {
    emergencyContact += `\nEmergency Contact\nRelationship: ${emergency_contact_relationship}\nFirst Name: ${emergency_contact_first_name}\nLast Name: ${emergency_contact_last_name}\nPhone Number: ${emergency_contact_phone_number}\nAuthorized Representative?: ${is_emergency_contact_authorized_representative}\n`;
  }

  // Appointment Information
  const apptInfo = `\nAppointment Information\nClinic:${appt_clinic} (${appt_clinic_raintree_code})\nDate: ${appt_date}\nTime: ${appt_time}\nProvider: ${appt_provider}`;

  // Session Notes
  let sessionNotes = "";
  if (typeof zt_session_notes !== "undefined" && zt_session_notes !== "") {
    sessionNotes += `\n\nSession Notes: ${zt_session_notes}`;
  }

  const summary = `${agentInfo}${reasonToSchedule}${postOp}${callerInfo}${patientInfo}${medicalInformation}${referringPhysician}${pcp}${referringProviderNote}${referredToIvy}${selfPay}${insurance}${secondInsurance}${parentGuardian}${emergencyContact}${apptInfo}${sessionNotes}`;

  return summary;
};

// Main
const createTransform = () => {
  const sessionId = ZT.getSessionId();
  const agentEmail =
    typeof agent_email !== "undefined" && agent_email !== ""
      ? agent_email
      : "System";
  const summaryInfo = getSummary();
  const link = createZingtreeURL(sessionId, agentEmail);

  const summaryData = {
    id: sessionId, // Session Id
    type: "New appointment - new patient",
    subType: "-", // Later iterations
    createdBy: agentEmail,
    createdDate: new Date(),
    updatedBy: agentEmail,
    updatedDateTime: new Date(),
    link: link,
    dataInformation: {
      clinic: getClinicInfo(),
      patient: getPatientInfo(sessionId, summaryInfo),
      appointment: getApptInfo(sessionId, summaryInfo),
    },
  };
  const summaryDataJson = JSON.stringify(summaryData);
  ZT.log("Summary Data JSON: " + summaryDataJson);
  ZT.setTransformData("summary_data_json", summaryDataJson);
};

createTransform();

