try {
    // Save old value
    const oldValue = ZT.getVariableValue('rt_task_subtype', undefined);
    ZT.setFormData('rt_task_subtype_old', oldValue);

    // Map variables to human-readable labels
    const subtypeMap = [
        { variable: 'rt_pec_no_referral_task_subtype', label: 'PEC - No Referral' },
        { variable: 'rt_pec_mva_task_subtype', label: 'PEC - MVA' },
        { variable: 'rt_pec_billing_task_subtype', label: 'PEC - Billing' },
        { variable: 'rt_pec_doctor_office_task_subtype', label: 'PEC - Doctors Office' },
        { variable: 'rt_pec_epa_task_subtype', label: 'PEC - Existing Patient Appointment' },
        { variable: 'rt_pec_general_inquiry_task_subtype', label: 'PEC - General Inquiry' },
        { variable: 'rt_pec_ici_ep_task_subtype', label: 'PEC - Insurance/Cost Inquiry - Existing Patient' },
        { variable: 'rt_pec_ici_np_task_subtype', label: 'PEC - Insurance/Cost Inquiry - New Patient' },
        { variable: 'rt_pec_prl_naf_task_subtype', label: 'PEC - Patient Running Late - No Appt Found' },
        { variable: 'rt_pec_tricare_task_subtype', label: 'PEC - Tricare' },
        { variable: 'rt_pec_uii_ep_task_subtype', label: 'PEC - Update Insurance Information - Existing Patient' },
        { variable: 'rt_pec_unpa_cfa_task_subtype', label: 'PEC - Update New Patient Appt - Cannot Find Appt' },
        { variable: 'rt_pec_unpa_peds_aba_task_subtype', label: 'PEC - Update New Patient Appt - PEDS/ABA' },
        { variable: 'rt_pec_unpa_rescheduled_3x_task_subtype', label: 'PEC - Update New Patient Appt - Rescheduled 3X' },
        { variable: 'rt_pec_va_task_subtype', label: 'PEC - VA' },
        { variable: 'rt_wccsr_ie_request_pec_task_subtype', label: 'WCCSR - IE Request PEC' },
        { variable: 'rt_pec_auth_task_subtype', label: 'PEC - Authorization' }
    ];

    // Collect all TRUE subtypes
    const selectedSubtypes = [];

    subtypeMap.forEach(item => {
        const value = ZT.getVariableValue(item.variable, false);
        if (value === true || value === 'true') {
            selectedSubtypes.push(item.label);
        }
    });

    // Set final value
    if (selectedSubtypes.length > 0) {
        ZT.setFormData('rt_task_subtype', selectedSubtypes.join(' & '));
    } else {
        ZT.setFormData('rt_task_subtype', undefined);
    }
}
catch (ex) {
    ZT.log("Error while setting rt_task_subtype: " + ex);
}

