/* ============================================================
 * Updated 2026-05-12 — fixed three bugs reported when the patient
 * number is invalid. Original script preserved at the bottom of
 * this file for review.
 *
 * Bugs fixed:
 *   1. setFormData was writing the wrong variable
 *      (is_patient_found instead of is_patient_details_valid),
 *      so name-mismatch cases never propagated to the form field.
 *   2. `?? true` defaulted is_patient_found to true when
 *      resourceType was missing — should default to false.
 *   3. .name.given[0] was read before checking whether the
 *      patient existed, throwing a TypeError on invalid patient
 *      numbers and halting the script before is_patient_details_valid
 *      could be written. Downstream logic node then read a stale
 *      value, which is what the client reported.
 *
 * Behavior preserved: the patient transform is still loaded
 * whenever the patient is found, even on first-name mismatch,
 * so a downstream "did you mean…" node can use the data.
 * ============================================================ */

// Default to false — only mark valid after we've actively confirmed
// the patient was found AND the name matches.
let is_patient_details_valid = false;

const result = actions.raintree__get_patient_by_patient_number;

// A real Raintree patient comes back with resourceType set.
// Anything else (missing object, missing resourceType) means "not found".
const is_patient_found = !!(result && result.resourceType);

ZT.log("Patient found: " + is_patient_found);

if (is_patient_found) {
    // Safe to read .name here — only entered this branch if patient exists.
    const patient_first_name_api = result.name?.given?.[0];
    ZT.log("API Name: " + patient_first_name_api);
    ZT.log("Form name: " + this.patient_first_name);

    if (patient_first_name_api && this.patient_first_name === patient_first_name_api) {
        is_patient_details_valid = true;
    }
}

// Write the correct variable so the downstream "is_patient_details_valid == true"
// logic node has an accurate value to read.
ZT.setFormData("is_patient_details_valid", is_patient_details_valid);

// Load patient transform on any found patient, even on name mismatch — keeps
// the original behavior so a downstream "did you mean…" node can use the data.
if (is_patient_found) {
    let patient = result;
    patient["pn"] = transforms.patient.pn;
    ZT.setTransformData("patient", patient);

    // Format Case Date Only
    function getDate(datetime) {
        if (!datetime) return '';
        return new Date(datetime).toISOString().split('T')[0];
    }

    ZT.setFormData("appointment_carestart_dateonly", getDate(new Date()));
}

/* ============================================================
 * ORIGINAL SCRIPT (commented out 2026-05-12) — preserved for review
 * ============================================================

let is_patient_details_valid = true;
let is_patient_found = actions.raintree__get_patient_by_patient_number.resourceType ?? true;
let patient_first_name_api = actions.raintree__get_patient_by_patient_number.name.given[0];
ZT.log("API Name: " + actions.raintree__get_patient_by_patient_number.name.given[0])
ZT.log("form name: " + patient_first_name)

if (patient_first_name !== patient_first_name_api || !is_patient_found) {
    is_patient_details_valid = false;
}
ZT.setFormData("is_patient_details_valid", is_patient_found);

if (is_patient_found) {
    let patient = actions.raintree__get_patient_by_patient_number;
    patient["pn"] = transforms.patient.pn;
    ZT.setTransformData("patient", patient)


    // Format Case Date Only
