function getStatusLabel(code) {
  if (code == null) return "No Request Made";

  return code === 200 || code === 201
    ? "Success"
    : "Failure";
}
let patientCode = actions.raintree__get_patient_by_patient_number?._zt_meta?.response?.code;
let guardianCode = actions?.raintree__create_guardian_v2?._zt_meta?.response?.code;
let emergencyCode = actions?.raintree_sandbox__create_emergency_contact?._zt_meta?.response?.code;
let caseCode = actions.send_case_details?._zt_meta?.response?.code;
let appointmentCode = actions?.raintree__update_appointment_by_id?._zt_meta?.response?.code;
let insuranceCode = actions?.raintree__create_patient_insurance?._zt_meta?.response?.code;

let patient_api_success = getStatusLabel(patientCode);
let guardian_api_success = getStatusLabel(guardianCode);
let emergency_contact_api_success = getStatusLabel(emergencyCode);
let case_api_success = getStatusLabel(caseCode);
let appointment_api_success = getStatusLabel(appointmentCode);
let patient_insurance_api_success = getStatusLabel(insuranceCode);


function hasApiFailure(codes) {
  return codes.some(code => getStatusLabel(code) === "Failure");
}

let isApiFailure = hasApiFailure([
  patientCode,
  guardianCode,
  emergencyCode,
  caseCode,
  appointmentCode,
  insuranceCode
]);

ZT.setFormData("isApiFailure", isApiFailure);
ZT.setFormData("patient_api_success", patient_api_success);
ZT.setFormData("guardian_api_success", guardian_api_success);
ZT.setFormData("emergency_contact_api_success", emergency_contact_api_success);
ZT.setFormData("case_api_success", case_api_success);
ZT.setFormData("appointment_api_success", appointment_api_success);
ZT.setFormData("patient_insurance_api_success", patient_insurance_api_success);

////

function add60Minutes(datetimeStr) {
  const date = new Date(datetimeStr);
  date.setMinutes(date.getMinutes() + 60);

  ZT.log('logging times: ' + datetimeStr + "Date: " + date )
  return date.toISOString();
}

let to_query_param = add60Minutes(appointment_datetime);
ZT.setFormData("to_query_param", to_query_param)

