// Build the PCP summary HTML.
// If primary_care_physician_last_name is empty/unset, show a "not provided"
// message instead of the name/phone formatting. Stored as a transform so the
// content node can render it with ${transforms.PCPsummary}.

const last = typeof primary_care_physician_last_name !== "undefined"
    ? primary_care_physician_last_name
    : "";

let PCPsummary;

if (last.trim() !== "") {
    // Name provided — render the original format. Pull each piece safely in
    // case first name or phone happens to be unset.
    const first = typeof primary_care_physician_first_name !== "undefined"
        ? primary_care_physician_first_name
        : "";
    const phone = typeof primary_care_physician_phone_number !== "undefined"
        ? primary_care_physician_phone_number
        : "";

    PCPsummary = `<p id="primary_care_physician_display"><strong>PCP:</strong> ${first} ${last} &nbsp; ${phone}</p>`;
} else {
    // No last name → fall back to the "not provided" message. Same <p> wrapper
    // and id so any downstream CSS/JS targeting that element still applies.
    PCPsummary = `<p id="primary_care_physician_display">The Primary Care Physician name was not provided</p>`;
}

// If the patient needs transportation for follow-up visits, append a line.
// This is true when either transportation variable indicates follow-up.
// Read each flag safely in case it was never set this session.
const needsTransportBoth = typeof needs_transportation_both !== "undefined"
    ? needs_transportation_both
    : "";
const needsTransportFollowUpOnly = typeof needs_transportation_follow_up_only !== "undefined"
    ? needs_transportation_follow_up_only
    : "";

const needsFollowUpTransport =
    needsTransportBoth === "Follow-Up" ||
    needsTransportBoth === "Both" ||
    needsTransportFollowUpOnly === "Follow-Up";

if (needsFollowUpTransport) {
    PCPsummary += `<p>Patient is interested in scheduling transportation for follow-up visits.</p>`;
}

ZT.setTransformData("PCPsummary", PCPsummary);

