// --- inputs -----------------------------------------------------------------
// patient_insurance_rt_code is written by Schedule New Patient node 200 (accepted insurance only).
// The subscriber fields come from Schedule New Patient node 149. appointment_carestart_dateonly
// (today, yyyy-mm-dd) is written by nodes 133 / 138.
let patient_insurance_rt_code = ZT.getVariableValue("patient_insurance_rt_code", "");
let subscriber_id = ZT.getVariableValue("subscriber_id", "");
let relationship = ZT.getVariableValue("subscriber_relationship_to_patient", "");
let subscriber_dob = ZT.getVariableValue("subscriber_dob", "");
let address_line_1 = ZT.getVariableValue("patient_address_line_1", "");
let address_line_2 = ZT.getVariableValue("patient_address_line_2", "");
let phone = ZT.getVariableValue("patient_phone_number", "");
let today = ZT.getVariableValue("appointment_carestart_dateonly", "");

// --- subscriber.dob: MM/DD/YYYY on node 149, yyyy-mm-dd for Raintree ----------
let subscriber_dob_iso = "";
if (subscriber_dob !== "") {
  let [month, day, year] = subscriber_dob.trim().split("/");
  subscriber_dob_iso = `${year}-${month.padStart(2, "0")}-${day.padStart(2, "0")}`;
}

// --- effectiveFrom is always Jan 1 of the current year (Kelsie, 10/1 and 10/8 calls) ---
let effective_year = today.slice(0, 4);

// --- outputs ----------------------------------------------------------------
// Everything the raintree__create_patient_insurance body reads that no other node produces.
// Insurance is sent by code only; Raintree fills in the name (confirmed on the 10/8 call).
ZT.setFormData("subscriber_dob_iso", subscriber_dob_iso);
ZT.setFormData("subscriber_relationship", relationship.trim().toLowerCase());
ZT.setFormData("subscriber_address", `${address_line_1} ${address_line_2}`.trim());
ZT.setFormData("subscriber_phone", phone.replace(/\D/g, ""));
ZT.setFormData("effective_year", effective_year);

// Router 163: only POST when an accepted insurance was picked and a member id was collected.
let is_create_patient_insurance = patient_insurance_rt_code !== "" && subscriber_id.trim() !== "";
ZT.setFormData("is_create_patient_insurance", is_create_patient_insurance ? "true" : "false");
